package com.shivhub.backend.service;
import java.math.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.shivhub.backend.dto.DistributorCreditNoteRequest; import com.shivhub.backend.entity.*; import com.shivhub.backend.repository.*; import lombok.RequiredArgsConstructor;
@Service @RequiredArgsConstructor public class DistributorCreditNoteService {
 private final DistributorCreditNoteRepository repository; private final PurchaseRepository purchaseRepository;
 @Transactional public DistributorCreditNote add(DistributorCreditNoteRequest r,User seller){ if(r==null||r.getPurchaseId()==null||r.getCreditNoteNumber()==null||r.getCreditNoteNumber().isBlank()||r.getAmount()==null||r.getAmount().signum()<=0)throw new RuntimeException("Purchase, credit-note number and amount are required"); Purchase p=purchaseRepository.findById(r.getPurchaseId()).orElseThrow(()->new RuntimeException("Purchase not found"));if(!p.getSeller().getId().equals(seller.getId()))throw new RuntimeException("Not authorized"); BigDecimal room=p.getGrandTotal().subtract(repository.totalForPurchase(p)).max(BigDecimal.ZERO);if(r.getAmount().compareTo(room)>0)throw new RuntimeException("Credit note cannot exceed unpaid purchase value of ₹"+room); DistributorCreditNote n=new DistributorCreditNote();n.setSeller(seller);n.setPurchase(p);n.setCreditNoteNumber(r.getCreditNoteNumber().trim());n.setCreditNoteDate(r.getCreditNoteDate());n.setAmount(r.getAmount().setScale(2,RoundingMode.HALF_UP));n.setGstAmount(r.getGstAmount()==null?BigDecimal.ZERO:r.getGstAmount());n.setAttachmentUrl(r.getAttachmentUrl());n.setReason(r.getReason());n.setRemarks(r.getRemarks());return repository.save(n); }
 @Transactional(readOnly=true) public List<Map<String,Object>> list(User seller){return repository.findBySellerOrderByCreditNoteDateDesc(seller).stream().map(n->{Map<String,Object> x=new LinkedHashMap<>();x.put("id",n.getId());x.put("creditNoteNumber",n.getCreditNoteNumber());x.put("creditNoteDate",n.getCreditNoteDate());x.put("amount",n.getAmount());x.put("gstAmount",n.getGstAmount());x.put("reason",n.getReason());x.put("remarks",n.getRemarks());x.put("attachmentUrl",n.getAttachmentUrl());x.put("purchaseId",n.getPurchase().getId());x.put("purchaseInvoiceNumber",n.getPurchase().getInvoiceNumber());return x;}).toList();}
}
